def fill_requests(apps, schema_editor):
    """Existing payouts: requested = amount; editors' payouts are staff commissions."""
    Payout = apps.get_model('wallet', 'Payout')
    for p in Payout.objects.select_related('author'):
        p.requested_cents = p.requested_cents or p.amount_cents
        if p.author.role in ('se', 'ce', 'marketing', 'finance'):
            p.category = 'staff'
        p.save(update_fields=['requested_cents', 'category'])


